import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadInter();



export type WorkflowAnimationProps = Record<string, any>;

const WorkflowAnimation: React.FC<WorkflowAnimationProps> = ({
  backgroundColor = "#f9fafb",
  transparentBackground = false,
  durationInSeconds = 8,
  nodeFillColor = "#ffffff",
  nodeStrokeColor = "#111827",
  lineColor = "#111827",
  textColor = "#111827",
  dollarColor = "#10b981",
  starColor = "#f59e0b",
  leftLabel = "BUSINESS",
  centerLabel = "BETH",
  rightLabel = "REVIEWER",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Canvas Coordinates
  const cx1 = width * 0.25;
  const cx2 = width * 0.5;
  const cx3 = width * 0.75;
  const cy = height * 0.45;
  const nodeRadius = 60;
  
  // Safe margins for connecting lines so they don't overlap transparent nodes
  const line1StartX = cx1 + nodeRadius + 10;
  const line1EndX = cx2 - nodeRadius - 10;
  const lineLength1 = line1EndX - line1StartX;

  const line2StartX = cx2 + nodeRadius + 10;
  const line2EndX = cx3 - nodeRadius - 10;
  const lineLength2 = line2EndX - line2StartX;

  // Proportional Timing Distribution
  const step = durationInFrames / 10;
  const tNode1 = 0;
  const tLine1 = Math.floor(step * 0.3);
  const tNode2 = Math.floor(step * 1);
  const tLine2 = Math.floor(step * 1.5);
  const tNode3 = Math.floor(step * 2);

  const tDollarIn = Math.floor(step * 3);
  const tDollarMove1 = Math.floor(step * 4);
  const tDollarMove2 = Math.floor(step * 5.2);
  const tDollarOut = Math.floor(step * 6.5);

  const tStarIn = Math.floor(step * 7.0);
  const tStarMove1 = Math.floor(step * 8.0);
  const tStarMove2 = Math.floor(step * 9.0);
  const tStarOut = Math.floor(step * 9.8);

  // Layout Element Springs
  const nodeScale1 = spring({ fps, frame: frame - tNode1, config: { damping: 14 } });
  const nodeScale2 = spring({ fps, frame: frame - tNode2, config: { damping: 14 } });
  const nodeScale3 = spring({ fps, frame: frame - tNode3, config: { damping: 14 } });

  const line1Progress = spring({ fps, frame: frame - tLine1, config: { damping: 20 } });
  const line2Progress = spring({ fps, frame: frame - tLine2, config: { damping: 20 } });

  // Dollar Icon Logic
  const dollarScaleIn = spring({ fps, frame: frame - tDollarIn, config: { damping: 12 } });
  const dollarScaleOut = spring({ fps, frame: frame - tDollarOut, config: { damping: 12, overshootClamping: true } });
  const dollarScale = Math.max(0, dollarScaleIn - dollarScaleOut);

  // Split driving value for sequenced node-to-node jumps
  const dollarDrive1 = spring({ fps, frame: frame - tDollarMove1, config: { damping: 14 } });
  const dollarDrive2 = spring({ fps, frame: frame - tDollarMove2, config: { damping: 14 } });
  const dollarDrive = dollarDrive1 + dollarDrive2;
  
  const dollarX = interpolate(dollarDrive, [0, 1, 2], [cx1, cx2, cx3], { extrapolateRight: "clamp" });
  const dollarJump = interpolate(
    dollarDrive,
    [0, 0.5, 1, 1.5, 2],
    [0, -100, 0, -100, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );
  
  // Star Icon Logic
  const starScaleIn = spring({ fps, frame: frame - tStarIn, config: { damping: 12 } });
  const starScaleOut = spring({ fps, frame: frame - tStarOut, config: { damping: 12, overshootClamping: true } });
  const starScale = Math.max(0, starScaleIn - starScaleOut);

  const starDrive1 = spring({ fps, frame: frame - tStarMove1, config: { damping: 14 } });
  const starDrive2 = spring({ fps, frame: frame - tStarMove2, config: { damping: 14 } });
  const starDrive = starDrive1 + starDrive2;
  
  const starX = interpolate(starDrive, [0, 1, 2], [cx3, cx2, cx1], { extrapolateRight: "clamp" });
  const starJump = interpolate(
    starDrive,
    [0, 0.5, 1, 1.5, 2],
    [0, -100, 0, -100, 0],
    { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <svg style={{ position: "absolute", top: 0, left: 0, width: "100%", height: "100%", overflow: "visible" }}>
        
        {/* Connecting Lines */}
        <line
          style={{ transition: "none" }}
          x1={line1StartX} y1={cy} x2={line1EndX} y2={cy}
          stroke={lineColor} strokeWidth={4}
          strokeDasharray={lineLength1}
          strokeDashoffset={lineLength1 * (1 - line1Progress)}
        />
        <line
          style={{ transition: "none" }}
          x1={line2StartX} y1={cy} x2={line2EndX} y2={cy}
          stroke={lineColor} strokeWidth={4}
          strokeDasharray={lineLength2}
          strokeDashoffset={lineLength2 * (1 - line2Progress)}
        />

        {/* Nodes & Labels */}
        <g style={{ transition: "none" }} transform={`translate(${cx1}, ${cy}) scale(${nodeScale1})`}>
          <circle cx={0} cy={0} r={nodeRadius} fill={nodeFillColor} stroke={nodeStrokeColor} strokeWidth={6} style={{ transition: "none" }} />
          <text y={110} fill={textColor} fontSize={42} fontWeight={700} textAnchor="middle" style={{ transition: "none" }}>{leftLabel}</text>
        </g>
        
        <g style={{ transition: "none" }} transform={`translate(${cx2}, ${cy}) scale(${nodeScale2})`}>
          <circle cx={0} cy={0} r={nodeRadius} fill={nodeFillColor} stroke={nodeStrokeColor} strokeWidth={6} style={{ transition: "none" }} />
          <text y={110} fill={textColor} fontSize={42} fontWeight={700} textAnchor="middle" style={{ transition: "none" }}>{centerLabel}</text>
        </g>
        
        <g style={{ transition: "none" }} transform={`translate(${cx3}, ${cy}) scale(${nodeScale3})`}>
          <circle cx={0} cy={0} r={nodeRadius} fill={nodeFillColor} stroke={nodeStrokeColor} strokeWidth={6} style={{ transition: "none" }} />
          <text y={110} fill={textColor} fontSize={42} fontWeight={700} textAnchor="middle" style={{ transition: "none" }}>{rightLabel}</text>
        </g>

        {/* Dynamic Tokens */}
        {dollarScale > 0 && (
          <g style={{ transition: "none" }} transform={`translate(${dollarX}, ${cy + dollarJump}) scale(${dollarScale})`}>
            <circle cx={0} cy={0} r={40} fill={dollarColor} style={{ transition: "none" }} />
            <g transform="translate(-20, -20)" style={{ transition: "none" }}>
              <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#ffffff" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }}>
                <line x1="12" y1="1" x2="12" y2="23"></line>
                <path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"></path>
              </svg>
            </g>
          </g>
        )}

        {starScale > 0 && (
          <g style={{ transition: "none" }} transform={`translate(${starX}, ${cy + starJump}) scale(${starScale})`}>
            <circle cx={0} cy={0} r={40} fill={starColor} style={{ transition: "none" }} />
            <g transform="translate(-20, -20)" style={{ transition: "none" }}>
              <svg width="40" height="40" viewBox="0 0 24 24" fill="#ffffff" stroke="none" style={{ transition: "none" }}>
                <path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"></path>
              </svg>
            </g>
          </g>
        )}
      </svg>
    </AbsoluteFill>
  );
};

export default WorkflowAnimation;